from jsonb_to_recordset($explainers$[{"question_id":"exam-ch34-v1-reading-houses-rocks","content_key":"[\"sentences\",\"In “People made them”, what does “them” mean?\",\"Cave houses.\",\"In “People made them”, what does “them” mean? Cave houses.\",\"\",[\"Cave houses.\",\"People.\",\"Photographs.\",\"Treehouses.\"],\"Cappadocia has many cave houses. People made them inside large rocks. The rocks in Cappadocia are kind of soft.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"them เป็นกรรมพหูพจน์ ย้อนดูสิ่งที่คนสร้างในประโยคก่อนหน้า คือ cave houses","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Where is the house? → In Serbia.","How many houses? → Three houses."]},{"question_id":"exam-ch34-v1-reading-houses-percent","content_key":"[\"sentences\",\"What percent of people live in cities?\",\"Fifty-six percent.\",\"What percent of people live in cities? Fifty-six percent.\",\"\",[\"Fifty percent.\",\"Fifty-six percent.\",\"Six percent.\",\"Sixty-five percent.\"],\"Fifty-six percent of the world’s people live in cities. Many people in the city live in apartments.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"what percentage ถามร้อยละ อ่านจำนวน fifty-six percent ที่อยู่หน้าคำว่า people","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Where is the house? → In Serbia.","How many houses? → Three houses."]},{"question_id":"exam-ch34-v1-reading-houses-water","content_key":"[\"sentences\",\"Where is the house?\",\"The house is over the water.\",\"Where is the house? The house is over the water.\",\"\",[\"The house is beside the water.\",\"The house is inside a cave.\",\"The house is over the water.\",\"The house is under the water.\"],\"The Drina River house is not a house beside the water. It’s a house over the water!\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"อ่าน not ให้ครบ ข้อความปฏิเสธ beside แล้วแก้เป็น over อย่าเลือกเพียงคำที่พบในเรื่อง","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Where is the house? → In Serbia.","How many houses? → Three houses."]},{"question_id":"exam-ch34-v1-reading-train-students","content_key":"[\"sentences\",\"What can students do on the train?\",\"Do their homework.\",\"What can students do on the train? Do their homework.\",\"\",[\"Clean the tracks.\",\"Cook dinner.\",\"Do their homework.\",\"Drive the train.\"],\"Students can do their homework or play a game on their phone. People read or talk. Some even go to sleep and wake up when they reach their stop.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"คำถามถามสิ่งที่ข้อความกล่าวถึงจริง เลือก do their homework ไม่ใช้กิจกรรมที่เพียงแต่เป็นไปได้","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Where is the house? → In Serbia.","How many houses? → Three houses."]},{"question_id":"exam-ch34-v1-reading-train-some","content_key":"[\"sentences\",\"What does the text say about trains at night?\",\"Some trains run day and night.\",\"What does the text say about trains at night? Some trains run day and night.\",\"\",[\"All trains run every ten minutes all night.\",\"All trains stop at night.\",\"No trains run on weekends.\",\"Some trains run day and night.\"],\"Some trains run all the time, day or night.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"Some หมายถึงบางขบวน ไม่ใช่ทุกขบวน อย่าขยายความเป็น all หรือ no","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Where is the house? → In Serbia.","How many houses? → Three houses."]},{"question_id":"exam-ch34-v1-reading-train-main","content_key":"[\"sentences\",\"Why is it useful to ride the L when roads are busy?\",\"Riders can travel and do other things while roads are busy.\",\"Why is it useful to ride the L when roads are busy? Riders can travel and do other things while roads are busy.\",\"\",[\"Riders always pay more than a taxi.\",\"Riders can travel and do other things while roads are busy.\",\"Riders cannot read on the train.\",\"Riders must drive the train themselves.\"],\"While drivers on the ground are stuck in traffic, riders on the L are on their way. Students can do their homework or play a game on their phone. People read or talk. Some even go to sleep and wake up when they reach their stop.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"ใจความรวมคือผู้โดยสารยังเดินทางได้เมื่อถนนรถติดและทำกิจกรรมอื่นได้ ไม่ใช่เลือกแค่คำเดียวจากเรื่อง","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Where is the house? → In Serbia.","How many houses? → Three houses."]},{"question_id":"exam-ch34-v1-reading-houses-main-practice-transfer","content_key":"[\"sentences\",\"Which title fits this part?\",\"Places people call home.\",\"Which title fits this part? Places people call home.\",\"\",[\"A school timetable.\",\"Cooking at home.\",\"How to catch a train.\",\"Places people call home.\"],\"Fifty-six percent of the world’s people live in cities. Many people in the city live in apartments. Others live around cities, in smaller towns called suburbs. There are many houses in the suburbs. Outside of cities and suburbs is the countryside. The countryside has a lot of space, so there are big houses and even farms. Houses, apartments, and farms are not the only places where people live. Some people live in really different houses!\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"ดูใจความที่ครอบคลุมบ้านและที่อยู่อาศัยหลายรูปแบบ","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Which title fits this part? Places people call home.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-houses-serbia-practice-transfer","content_key":"[\"sentences\",\"Which country is the Drina River house in?\",\"Serbia.\",\"Which country is the Drina River house in? Serbia.\",\"\",[\"Indonesia.\",\"Japan.\",\"Serbia.\",\"Turkey.\"],\"The Drina River house is not a house beside the water. It’s a house over the water! This house is in Serbia. People love to visit and take photographs of it.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"This house ย้อนถึงบ้านเหนือแม่น้ำที่กล่าวก่อนหน้า อยู่ใน Serbia","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Which country is the Drina River house in? Serbia.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-houses-rocks-practice-transfer","content_key":"[\"sentences\",\"Where did people build the cave houses?\",\"Inside large rocks.\",\"Where did people build the cave houses? Inside large rocks.\",\"\",[\"Inside buses.\",\"Inside large rocks.\",\"On train platforms.\",\"Under the sea.\"],\"In Cappadocia, Turkey, you can find very different houses! Cappadocia has many cave houses. People made them inside large rocks. The rocks in Cappadocia are kind of soft. People have lived in these cave homes for thousands of years.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"People made them inside large rocks บอกตำแหน่งที่สร้างบ้านถ้ำ","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Where did people build the cave houses? Inside large rocks.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-train-name-practice-transfer","content_key":"[\"sentences\",\"What is the L?\",\"An overhead train.\",\"What is the L? An overhead train.\",\"\",[\"A beach.\",\"A cave house.\",\"A taxi company.\",\"An overhead train.\"],\"In Chicago, the overhead train is called the L. The tracks make a loop around the city center and then run out in all directions to the different parts of the city. The tracks are supported by massive steel columns.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"the overhead train is called the L บอกชื่อรถไฟ","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["What is the L? An overhead train.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-train-support-practice-transfer","content_key":"[\"sentences\",\"What are the columns made of?\",\"Steel.\",\"What are the columns made of? Steel.\",\"\",[\"Glass.\",\"Paper.\",\"Steel.\",\"Wood.\"],\"In Chicago, the overhead train is called the L. The tracks make a loop around the city center and then run out in all directions to the different parts of the city. The tracks are supported by massive steel columns.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"steel ขยาย columns บอกวัสดุของเสาที่รองรับราง","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["What are the columns made of? Steel.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-train-platform-practice-transfer","content_key":"[\"sentences\",\"Where do the stairs and elevator take riders?\",\"The platform.\",\"Where do the stairs and elevator take riders? The platform.\",\"\",[\"A treehouse.\",\"Diamond Beach.\",\"Inside a taxi.\",\"The platform.\"],\"Riding the train is easy. Riders climb stairs or take an elevator from the sidewalk to the platform. They buy a ticket, go through a gate, and wait for the next train to take them where they want to go. A train ticket costs less than a taxi ride. At busy times, trains come as often as every ten minutes. At night and on weekends, they do not come as often. Some trains run all the time, day or night.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"from ... to ... บอกจุดเริ่มต้นและปลายทาง ปลายทางคือ platform","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Where do the stairs and elevator take riders? The platform.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-train-price-practice-transfer","content_key":"[\"sentences\",\"Which costs more: a taxi ride or a train ride?\",\"A taxi ride.\",\"Which costs more: a taxi ride or a train ride? A taxi ride.\",\"\",[\"A taxi ride.\",\"A train ride.\",\"Both are free.\",\"Both cost the same.\"],\"Riding the train is easy. Riders climb stairs or take an elevator from the sidewalk to the platform. They buy a ticket, go through a gate, and wait for the next train to take them where they want to go. A train ticket costs less than a taxi ride. At busy times, trains come as often as every ten minutes. At night and on weekends, they do not come as often. Some trains run all the time, day or night.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"รถไฟ costs less than taxi แปลว่ารถแท็กซี่แพงกว่า","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Which costs more: a taxi ride or a train ride? A taxi ride.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-train-frequency-practice-transfer","content_key":"[\"sentences\",\"When do trains come more often?\",\"At busy times.\",\"When do trains come more often? At busy times.\",\"\",[\"At busy times.\",\"At night.\",\"On weekends.\",\"They always come just as often.\"],\"Riding the train is easy. Riders climb stairs or take an elevator from the sidewalk to the platform. They buy a ticket, go through a gate, and wait for the next train to take them where they want to go. A train ticket costs less than a taxi ride. At busy times, trains come as often as every ten minutes. At night and on weekends, they do not come as often. Some trains run all the time, day or night.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"not as often ตอนกลางคืนและสุดสัปดาห์แปลว่าช่วงคนมากรถไฟถี่กว่า","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["When do trains come more often? At busy times.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-houses-percent-practice-transfer","content_key":"[\"sentences\",\"Where do many people in cities live?\",\"In apartments.\",\"Where do many people in cities live? In apartments.\",\"\",[\"In apartments.\",\"On train tracks.\",\"Only in caves.\",\"Only on farms.\"],\"Fifty-six percent of the world’s people live in cities. Many people in the city live in apartments. Others live around cities, in smaller towns called suburbs. There are many houses in the suburbs. Outside of cities and suburbs is the countryside. The countryside has a lot of space, so there are big houses and even farms. Houses, apartments, and farms are not the only places where people live. Some people live in really different houses!\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"Many people in the city live in apartments เป็นหลักฐานตรง","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Where do many people in cities live? In apartments.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-houses-space-practice-transfer","content_key":"[\"sentences\",\"Where is there space for big houses and farms?\",\"The countryside.\",\"Where is there space for big houses and farms? The countryside.\",\"\",[\"A small elevator.\",\"A train platform.\",\"Inside a taxi.\",\"The countryside.\"],\"Fifty-six percent of the world’s people live in cities. Many people in the city live in apartments. Others live around cities, in smaller towns called suburbs. There are many houses in the suburbs. Outside of cities and suburbs is the countryside. The countryside has a lot of space, so there are big houses and even farms. Houses, apartments, and farms are not the only places where people live. Some people live in really different houses!\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"The countryside has a lot of space บอกเหตุที่มีบ้านใหญ่และฟาร์ม","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Where is there space for big houses and farms? The countryside.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-houses-water-practice-transfer","content_key":"[\"sentences\",\"Is the Drina River house beside the water?\",\"No. It is over the water.\",\"Is the Drina River house beside the water? No. It is over the water.\",\"\",[\"No. It is in the water.\",\"No. It is over the water.\",\"No. It is under the water.\",\"Yes. It is beside the water.\"],\"The Drina River house is not a house beside the water. It’s a house over the water! This house is in Serbia. People love to visit and take photographs of it.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"อ่าน not beside แล้วอ่านประโยคถัดไป: บ้านอยู่ over the water จึงตอบ No และบอกตำแหน่งที่ถูกต้อง","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Is the Drina River house beside the water? No. It is over the water.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-houses-bali-practice-transfer","content_key":"[\"sentences\",\"Which country is Bali in?\",\"Indonesia.\",\"Which country is Bali in? Indonesia.\",\"\",[\"Indonesia.\",\"Japan.\",\"Serbia.\",\"Turkey.\"],\"Treehouses are a lot of fun, but do you want to live in one? In Bali, Indonesia, you can try living in the famous Rumah Pohon Treehouse. There are three treehouses there that you can stay in. They are near the beautiful Diamond Beach.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"Bali, Indonesia ใช้ชื่อประเทศขยายชื่อสถานที่","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Which country is Bali in? Indonesia.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-houses-soft-practice-transfer","content_key":"[\"sentences\",\"What are the rocks in Cappadocia like?\",\"They are kind of soft.\",\"What are the rocks in Cappadocia like? They are kind of soft.\",\"\",[\"They are all underwater.\",\"They are kind of soft.\",\"They are made of steel.\",\"They are train tracks.\"],\"In Cappadocia, Turkey, you can find very different houses! Cappadocia has many cave houses. People made them inside large rocks. The rocks in Cappadocia are kind of soft. People have lived in these cave homes for thousands of years.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"The rocks ... are kind of soft บอกลักษณะหิน","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["What are the rocks in Cappadocia like? They are kind of soft.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-houses-years-practice-transfer","content_key":"[\"sentences\",\"Did people start living in these caves yesterday?\",\"No. They have lived there for thousands of years.\",\"Did people start living in these caves yesterday? No. They have lived there for thousands of years.\",\"\",[\"No one lives in the caves.\",\"No. They have lived there for thousands of years.\",\"No. They moved in this morning.\",\"Yes. They moved in yesterday.\"],\"In Cappadocia, Turkey, you can find very different houses! Cappadocia has many cave houses. People made them inside large rocks. The rocks in Cappadocia are kind of soft. People have lived in these cave homes for thousands of years.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"for thousands of years หมายถึงอาศัยมานานหลายพันปี ไม่ใช่เพิ่งย้ายเข้าเมื่อวาน","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Did people start living in these caves yesterday? No. They have lived there for thousands of years.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-train-noise-practice-transfer","content_key":"[\"sentences\",\"Why should you look up?\",\"A train is passing overhead.\",\"Why should you look up? A train is passing overhead.\",\"\",[\"A bus is in a cave.\",\"A taxi is underground.\",\"A train is passing overhead.\",\"It is raining heavily.\"],\"The sun is shining, but you think you hear thunder. Look up! A train is passing over your head!\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"Look up ตามด้วยรถไฟผ่านเหนือหัว เป็นเหตุให้มองขึ้น","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Why should you look up? A train is passing overhead.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-train-sequence-practice-transfer","content_key":"[\"sentences\",\"What do riders do first?\",\"Buy a ticket.\",\"What do riders do first? Buy a ticket.\",\"\",[\"Buy a ticket.\",\"Go through the gate.\",\"Reach their stop.\",\"Wait for the next train.\"],\"Riding the train is easy. Riders climb stairs or take an elevator from the sidewalk to the platform. They buy a ticket, go through a gate, and wait for the next train to take them where they want to go. A train ticket costs less than a taxi ride. At busy times, trains come as often as every ten minutes. At night and on weekends, they do not come as often. Some trains run all the time, day or night.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"รายการการกระทำเรียง buy a ticket ก่อน go through a gate และ wait","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["What do riders do first? Buy a ticket.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-train-busy-practice-transfer","content_key":"[\"sentences\",\"At busy times, how many minutes can there be between trains?\",\"Ten minutes.\",\"At busy times, how many minutes can there be between trains? Ten minutes.\",\"\",[\"Fifty-six hours.\",\"One month.\",\"Ten days.\",\"Ten minutes.\"],\"Riding the train is easy. Riders climb stairs or take an elevator from the sidewalk to the platform. They buy a ticket, go through a gate, and wait for the next train to take them where they want to go. A train ticket costs less than a taxi ride. At busy times, trains come as often as every ten minutes. At night and on weekends, they do not come as often. Some trains run all the time, day or night.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"every ten minutes คือช่วงห่างสิบนาที","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["At busy times, how many minutes can there be between trains? Ten minutes.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-train-some-practice-transfer","content_key":"[\"sentences\",\"Do all trains run all day and night?\",\"The text only says some trains.\",\"Do all trains run all day and night? The text only says some trains.\",\"\",[\"No trains run at night.\",\"Only taxis run at night.\",\"The text only says some trains.\",\"Yes, every train does.\"],\"Riding the train is easy. Riders climb stairs or take an elevator from the sidewalk to the platform. They buy a ticket, go through a gate, and wait for the next train to take them where they want to go. A train ticket costs less than a taxi ride. At busy times, trains come as often as every ten minutes. At night and on weekends, they do not come as often. Some trains run all the time, day or night.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"Some ไม่ได้แปลว่า all ห้ามขยายคำกล่าวเกินหลักฐาน","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Do all trains run all day and night? The text only says some trains.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-train-main-practice-transfer","content_key":"[\"sentences\",\"Cars are stuck in traffic. What are the train riders doing?\",\"They are still travelling.\",\"Cars are stuck in traffic. What are the train riders doing? They are still travelling.\",\"\",[\"They are all driving cars.\",\"They are building a road.\",\"They are still travelling.\",\"They are waiting behind buses.\"],\"While drivers on the ground are stuck in traffic, riders on the L are on their way. Students can do their homework or play a game on their phone. People read or talk. Some even go to sleep and wake up when they reach their stop.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"While บอกสองเหตุการณ์ในเวลาเดียวกัน: คนขับรถติดอยู่บนถนน แต่ผู้โดยสารรถไฟยังเดินทางต่อได้","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Cars are stuck in traffic. What are the train riders doing? They are still travelling.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-houses-main-assessment-transfer","content_key":"[\"sentences\",\"What do we learn about homes?\",\"People live in different kinds of homes.\",\"What do we learn about homes? People live in different kinds of homes.\",\"\",[\"All houses are in cities.\",\"Everyone lives on a farm.\",\"Nobody lives in apartments.\",\"People live in different kinds of homes.\"],\"Fifty-six percent of the world’s people live in cities. Many people in the city live in apartments. Others live around cities, in smaller towns called suburbs. There are many houses in the suburbs. Outside of cities and suburbs is the countryside. The countryside has a lot of space, so there are big houses and even farms. Houses, apartments, and farms are not the only places where people live. Some people live in really different houses!\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"ดูภาพรวม บ้านมีหลายชนิด ไม่เลือกคำกล่าวที่ใช้ everyone หรือ all เกินข้อความ","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["What do we learn about homes? People live in different kinds of homes.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-houses-suburbs-assessment-transfer","content_key":"[\"sentences\",\"What do we call a small town around a city?\",\"A suburb.\",\"What do we call a small town around a city? A suburb.\",\"\",[\"A platform.\",\"A railway.\",\"A suburb.\",\"A treehouse.\"],\"Fifty-six percent of the world’s people live in cities. Many people in the city live in apartments. Others live around cities, in smaller towns called suburbs. There are many houses in the suburbs. Outside of cities and suburbs is the countryside. The countryside has a lot of space, so there are big houses and even farms. Houses, apartments, and farms are not the only places where people live. Some people live in really different houses!\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"ใช้คำอธิบาย smaller towns around cities กับตัวอย่างใหม่ คือ suburb","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["What do we call a small town around a city? A suburb.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-houses-serbia-assessment-transfer","content_key":"[\"sentences\",\"You want to see the Drina River house. Where should you go?\",\"Serbia.\",\"You want to see the Drina River house. Where should you go? Serbia.\",\"\",[\"Indonesia.\",\"Japan.\",\"Serbia.\",\"Turkey.\"],\"The Drina River house is not a house beside the water. It’s a house over the water! This house is in Serbia. People love to visit and take photographs of it.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"ตามชื่อบ้าน Drina River house ไปยัง This house is in Serbia","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["You want to see the Drina River house. Where should you go? Serbia.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-houses-rocks-assessment-transfer","content_key":"[\"sentences\",\"How did people build the cave houses?\",\"People built homes inside rocks.\",\"How did people build the cave houses? People built homes inside rocks.\",\"\",[\"People built homes above the sea.\",\"People built homes inside rocks.\",\"People built rocks inside trains.\",\"The houses were made from trees.\"],\"In Cappadocia, Turkey, you can find very different houses! Cappadocia has many cave houses. People made them inside large rocks. The rocks in Cappadocia are kind of soft. People have lived in these cave homes for thousands of years.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"made them inside large rocks: them คือบ้านถ้ำ ไม่ใช่ต้นไม้","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["How did people build the cave houses? People built homes inside rocks.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-train-name-assessment-transfer","content_key":"[\"sentences\",\"Where can you ride the train called the L?\",\"Chicago.\",\"Where can you ride the train called the L? Chicago.\",\"\",[\"Bali.\",\"Cappadocia.\",\"Chicago.\",\"Tokyo.\"],\"In Chicago, the overhead train is called the L. The tracks make a loop around the city center and then run out in all directions to the different parts of the city. The tracks are supported by massive steel columns.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"In Chicago ระบุเมืองที่รถไฟเหนือถนนมีชื่อ the L","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Where can you ride the train called the L? Chicago.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-train-support-assessment-transfer","content_key":"[\"sentences\",\"What do the steel columns do?\",\"They hold up the tracks.\",\"What do the steel columns do? They hold up the tracks.\",\"\",[\"They drive the taxis.\",\"They form the river.\",\"They hold up the tracks.\",\"They sell train tickets.\"],\"In Chicago, the overhead train is called the L. The tracks make a loop around the city center and then run out in all directions to the different parts of the city. The tracks are supported by massive steel columns.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"supported by บอกหน้าที่รองรับราง ไม่ใช่หน้าที่ขายตั๋ว","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["What do the steel columns do? They hold up the tracks.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-train-platform-assessment-transfer","content_key":"[\"sentences\",\"You cannot use the stairs. How can you get to the platform?\",\"Take an elevator.\",\"You cannot use the stairs. How can you get to the platform? Take an elevator.\",\"\",[\"Swim there.\",\"Take a plane.\",\"Take an elevator.\",\"There is no other way.\"],\"Riding the train is easy. Riders climb stairs or take an elevator from the sidewalk to the platform. They buy a ticket, go through a gate, and wait for the next train to take them where they want to go. A train ticket costs less than a taxi ride. At busy times, trains come as often as every ten minutes. At night and on weekends, they do not come as often. Some trains run all the time, day or night.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"stairs or an elevator มีอีกทางเลือกคือลิฟต์","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["You cannot use the stairs. How can you get to the platform? Take an elevator.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-train-price-assessment-transfer","content_key":"[\"sentences\",\"You want to spend less money. Should you take a train or a taxi?\",\"The train.\",\"You want to spend less money. Should you take a train or a taxi? The train.\",\"\",[\"Both are free.\",\"Both have the same price.\",\"The taxi.\",\"The train.\"],\"Riding the train is easy. Riders climb stairs or take an elevator from the sidewalk to the platform. They buy a ticket, go through a gate, and wait for the next train to take them where they want to go. A train ticket costs less than a taxi ride. At busy times, trains come as often as every ten minutes. At night and on weekends, they do not come as often. Some trains run all the time, day or night.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"less than หมายถึงน้อยกว่า รถไฟจึงถูกกว่าแท็กซี่ตามข้อความ","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["You want to spend less money. Should you take a train or a taxi? The train.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-train-frequency-assessment-transfer","content_key":"[\"sentences\",\"Do trains come as often on weekends as at busy times?\",\"No. They come less often.\",\"Do trains come as often on weekends as at busy times? No. They come less often.\",\"\",[\"No. They come less often.\",\"There are no trains on weekends.\",\"They come every ten seconds.\",\"Yes. They come just as often.\"],\"Riding the train is easy. Riders climb stairs or take an elevator from the sidewalk to the platform. They buy a ticket, go through a gate, and wait for the next train to take them where they want to go. A train ticket costs less than a taxi ride. At busy times, trains come as often as every ten minutes. At night and on weekends, they do not come as often. Some trains run all the time, day or night.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"not ... as often แปลว่ามาน้อยครั้งกว่า เปรียบเทียบ weekends กับ busy times ไม่ได้แปลว่าไม่มีรถไฟเลย","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Do trains come as often on weekends as at busy times? No. They come less often.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-houses-percent-assessment-transfer","content_key":"[\"sentences\",\"Do all people in cities live in apartments?\",\"The text only says many people do.\",\"Do all people in cities live in apartments? The text only says many people do.\",\"\",[\"Everyone lives on a farm.\",\"No one lives in apartments.\",\"The text only says many people do.\",\"Yes, everyone does.\"],\"Fifty-six percent of the world’s people live in cities. Many people in the city live in apartments. Others live around cities, in smaller towns called suburbs. There are many houses in the suburbs. Outside of cities and suburbs is the countryside. The countryside has a lot of space, so there are big houses and even farms. Houses, apartments, and farms are not the only places where people live. Some people live in really different houses!\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"Many หมายถึงจำนวนมาก ไม่ใช่ทุกคน","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["Do all people in cities live in apartments? The text only says many people do.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-houses-space-assessment-transfer","content_key":"[\"sentences\",\"There is a lot of space in the countryside. What can people have there?\",\"Big houses and farms.\",\"There is a lot of space in the countryside. What can people have there? Big houses and farms.\",\"\",[\"Big houses and farms.\",\"Only small houses.\",\"Only small rooms.\",\"Only train tracks.\"],\"Fifty-six percent of the world’s people live in cities. Many people in the city live in apartments. Others live around cities, in smaller towns called suburbs. There are many houses in the suburbs. Outside of cities and suburbs is the countryside. The countryside has a lot of space, so there are big houses and even farms. Houses, apartments, and farms are not the only places where people live. Some people live in really different houses!\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"so เชื่อมเหตุมีพื้นที่มากกับผลคือบ้านใหญ่และฟาร์ม","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["There is a lot of space in the countryside. What can people have there? Big houses and farms.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-houses-water-assessment-transfer","content_key":"[\"sentences\",\"What is below the Drina River house?\",\"Water.\",\"What is below the Drina River house? Water.\",\"\",[\"A farm.\",\"A road.\",\"A train.\",\"Water.\"],\"The Drina River house is not a house beside the water. It’s a house over the water! This house is in Serbia. People love to visit and take photographs of it.\",\"\"]","pattern_key":"exam-reading","title_th":"หาหลักฐานในข้อความ","rule_th":"อ่านคำถามว่าถามใคร ที่ไหน จำนวน วิธี หรือความหมาย แล้วหาใจความที่ตอบเรื่องเดียวกันในข้อความ","clue_th":"บ้านอยู่ over the water ดังนั้นสิ่งที่อยู่ข้างล่างบ้านคือ water","caution_th":null,"contrasts":[{"label_th":"รูปแบบแรก","text":"Where? → a place"},{"label_th":"อีกตัวอย่าง","text":"How many? → a number"}],"examples":["What is below the Drina River house? Water.","Where is the house? → In Serbia."]},{"question_id":"exam-ch34-v1-reading-houses-bali-assessment-transfer","content_key":"[\"sentences\",\"What kind of home can visitors stay in near Diamond Beach?\",\"A treehouse.\",\"What kind of home can visitors stay in near Diamond Beach? A treehouse.\",\"\",[\"A cave house.\",\"A home on a train.\",\"A home under the sea.\",\"A treehouse.\"],\"Treehouses are a lot of fun, but do you want to live in one? In Bali, Indonesia, you can try living in the famous Rumah Pohon Treehouse. There are three treehouses there that you can stay in. They are near the beautiful Diamond Beach.\",\"\"]","